import java.io.BufferedReader;
import java.io.InputStreamReader;

/**
 * Variant 4: Using BufferedReader, minimal structure, output with StringBuilder
 */
public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output = new StringBuilder();
        int n = Integer.parseInt(br.readLine().trim());
        if (n > 11) {
            output.append("0\n");
            System.out.print(output);
            return;
        }

        Point[] pts = new Point[n];
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            int v = Integer.parseInt(parts[0]);
            int w = Integer.parseInt(parts[1]);
            int x = Integer.parseInt(parts[2]);
            int y = Integer.parseInt(parts[3]);
            int z = Integer.parseInt(parts[4]);
            pts[i] = new Point(v, w, x, y, z);
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            boolean isGood = true;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (i != j && i != k && j != k) {
                        Point one = pts[j];
                        Point two = pts[k];
                        Point three = pts[i];
                        Point lol2 = new Point(one.v - three.v, one.w - three.w, one.x - three.x, one.y - three.y, one.z - three.z);
                        Point lol1 = new Point(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z);
                        if (angle(lol1, lol2)) {
                            isGood = false;
                        }
                    }
                }
            }
            if (isGood) {
                count++;
                output.append(i + 1).append("\n");
            }
        }
        if (count == 0) {
            output.append("0\n");
        } else {
            output.append(count).append("\n");
            System.out.print(output);
        }
    }

    static boolean angle(Point a, Point b) {
        double amag = a.mag();
        double bmag = b.mag();
        double dotProduct = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
        return Math.toDegrees(Math.acos(dotProduct / (amag * bmag))) < 90;
    }

    static class Point {
        int v, w, x, y, z;
        Point(int v, int w, int x, int y, int z) {
            this.v = v; this.w = w; this.x = x; this.y = y; this.z = z;
        }
        double mag() {
            return Math.sqrt(v * v + w * w + x * x + y * y + z * z);
        }
    }
}
